// Copies the fee and forecast logic the app uses into functions/shared, so the
// assistant (functions/chatbot.js) gives the same numbers as the Analytics page.
// Runs before every functions deploy (firebase.json predeploy). Do not edit the copies.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const out = resolve(root, 'functions/shared')
mkdirSync(out, { recursive: true })

const header = '// GENERATED by scripts/sync-functions-shared.mjs from src/. Do not edit.\n'
for (const name of ['feeCalc', 'capacity', 'revenueForecast']) {
  const src = readFileSync(resolve(root, `src/utils/${name}.js`), 'utf8')
    .replace(/from '\.\/(feeCalc|capacity)\.js'/g, "from './$1.mjs'")
  writeFileSync(resolve(out, `${name}.mjs`), header + src)
}
writeFileSync(resolve(out, 'act1080Fees.json'), readFileSync(resolve(root, 'src/data/act1080Fees.json')))
console.log('functions/shared synced')
